insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('m-collection-s750','milestone','S750''s collection: the display build for S748''s records, seven records by plan','S750 (2026-11-28, the routine''s 13:12Z run): display build 366c5bbc7b2d is live (#3953, 91bffc66): 18,753 records, 32 at three older builds; it carried S748''s 41 records to the page. Plan s750a turns coverage true at seven records (migrate 46161770404; handoff 751 holds its result). The found-pages code landed off for every college (#3954). No paid read, no outline rows.',array['program-requirements','collection','milestone'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('d-cerritos-02235-person-confirmed-s750','decision','Cerritos 02235 left plan s750a: Sam''s confirm stands on the live record','S750 conductor: the pre-read for plan s750a found Sam''s confirm verdict of 2026-10-15 (verdict 36) on Cerritos 02235''s live record, so the plan narrowed from eight records to seven and the record stays untouched; its coverage still reads false, for a person''s look. A plan''s expectation that no row is checked is a forecast, not proof, without a live read.',array['program-requirements','cerritos','person-settled','decision'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('d-found-pages-gate-held-s750','decision','The found-pages none-wrong gate was held; the code landed off, with no deploy and no probe','S750 conductor: on live recall the found-pages gate (recall 0.8 over 30 tested, none wrong) held every college back; no paid read ran. The conductor did not loosen a gate its reader had just passed; #3954 lands off. Next: read the nine wrongs, decide under a Fable reader whether an oracle''s error counts, then a free capture, the deploy, the Skyline 05809 probe and a no_state_course_list gap rule.',array['program-requirements','found-pages','gate','decision'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('d-madera-39810-for-a-person-s750','decision','Madera 39810 left plan s750a for a person: its page counts the course it omits','S750 conductor: Madera 39810 was dropped from plan s750a (state_course_not_on_page) before its reader. Its page heads the core "41-47 units" over 39.5 units of courses, so the page counts the course it omits and the reading does not apply. The record waits on a person''s look.',array['program-requirements','madera','coverage','decision'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('d-canyons-37868-needs-pin-s750','decision','College of the Canyons 37868 needs a pdf_pages pin for page 78 before any read','S750 conductor: run 46121986278 stopped at the price step, $0, nothing filed. Staging holds College of the Canyons 37868 as not_found (rule B then A), and a fresh free capture (46157462134, claude/s750-piles-coc) reads the same. Next: a pdf_pages pin for page 78, a free capture, then a paid read of about $0.10.',array['program-requirements','college-of-the-canyons','pin','decision'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('f-found-pages-live-recall-counts-wrongs-s750','fact','Found pages: live recall counted a wrong at each of five colleges; four of nine look like the oracle','S750: recall on filed pages cleared eleven colleges, but live recall at the capture cleared none of five: Skyline 42 tested, 35 right, 1 wrong; San Mateo 55, 47, 3; Diablo Valley 200, 189, 2; San Joaquin Delta 204, 197, 1; Gavilan 81, 72, 2. Of the nine wrongs, four look like the oracle''s error (a passing record read from another award''s page), two are an older catalog version, three are unread.',array['program-requirements','found-pages','recall','fact'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('f-display-no-list-holdback-s750','fact','The display build''s no-list hold-back read coverage.basis alone','S750, the found-pages reader''s MAJOR: the display build''s no_state_list() read coverage.basis alone, so a record scored against no state course list would have reached CPL Pathways as "0 of 0 placed". Fixed on claude/s750-found (f654050f, #3954); the build stamp and its 18,754 statements are unchanged. A new coverage reason needs the display hold-back checked beside the scorer.',array['program-requirements','display','found-pages','fact'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28'),
('p-preread-catches-person-confirm-s750','procedure','A plan''s live pre-read looks for a person''s confirm on every record before the apply','S750: plan s750a and its Sonnet reader both expected no checked row; the conductor''s live pre-read found a matching confirm on one record (Cerritos 02235, Sam, 2026-10-15). Before any apply the conductor reads run, record, checks and confirms live for every row; a person-settled row leaves the plan, with no second reader round for a row removed.',array['program-requirements','conductor','pre-read','procedure'],'proposed','docs/session_751_handoff.md',null,null,'SkySandpiper (S750)','2026-11-28')
on conflict (slug) do nothing;

