  and m.author = 'SkySandpiper (S750)'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');

select slug, kind, status, length(summary) as summary_len from public.cpl_memory
where slug in ('m-collection-s750','d-cerritos-02235-person-confirmed-s750','d-found-pages-gate-held-s750','d-madera-39810-for-a-person-s750','d-canyons-37868-needs-pin-s750','f-found-pages-live-recall-counts-wrongs-s750','f-display-no-list-holdback-s750','p-preread-catches-person-confirm-s750')
  and author = 'SkySandpiper (S750)'
